mapper.select:
SELECT r.resume_id , r.title , r.template_id , p.introduction , r.source_type , r.source_file_name , r.created_at , r.updated_at FROM resumes r LEFT JOIN resume_profile p ON p.resume_id = r.resume_id AND p.use_yn = 'Y' WHERE r.user_id = #{userId} AND r.use_yn = 'Y'
AND template_id = #{templateId}
ORDER BY r.updated_at DESC

mapper.insert:
INSERT INTO resumes (
    user_id
    , title
    , template_id
    , use_yn
    , created_at
    , updated_at
) VALUES (
    #{userId}
    , #{title}
    , #{templateId}
    , 'Y'
    , CURRENT_TIMESTAMP
    , CURRENT_TIMESTAMP
)

INSERT INTO resume_profile (
    resume_id
    , name
    , email
    , phone
    , address
    , profile_image_id
    , profile_image_url
    , birth_date
    , introduction
    , use_yn
    , created_at
    , updated_at
) VALUES (
    #{resumeId}
    , #{name}
    , #{email}
    , #{phone}
    , #{address}
    , #{profileImageId}
    , #{profileImageUrl}
    , #{birthDate}
    , #{introduction}
    , 'Y'
    , CURRENT_TIMESTAMP
    , CURRENT_TIMESTAMP
)

