mapper.update:
UPDATE resumes
SET updated_at = CURRENT_TIMESTAMP

    , title = #{title}


    , template_id = #{templateId}

WHERE resume_id = #{resumeId}
    AND use_yn = 'Y'

    AND user_id = #{userId}

UPDATE resumes SET use_yn = 'N' , updated_at = CURRENT_TIMESTAMP WHERE use_yn = 'Y'
AND resume_id = #{resumeId}
AND user_id = #{userId}
AND 1 = 0

UPDATE resume_profile SET use_yn = 'N' , updated_at = CURRENT_TIMESTAMP WHERE use_yn = 'Y'
AND profile_id = #{profileId}
AND resume_id = #{resumeId}
AND 1 = 0

UPDATE resume_skill SET use_yn = 'N' , updated_at = CURRENT_TIMESTAMP WHERE use_yn = 'Y'
AND skill_id = #{skillId}
