AND 1 = 0

UPDATE resume_education SET use_yn = 'N' , updated_at = CURRENT_TIMESTAMP WHERE use_yn = 'Y'
AND education_id = #{educationId}
AND resume_id = #{resumeId}
AND 1 = 0

UPDATE resume_experience SET use_yn = 'N' , updated_at = CURRENT_TIMESTAMP WHERE use_yn = 'Y'
