UPDATE resume_cover_letter SET use_yn = 'N' , updated_at = CURRENT_TIMESTAMP WHERE use_yn = 'Y'
AND cover_letter_id = #{coverLetterId}
AND resume_id = #{resumeId}
AND 1 = 0
